package ais.action.master.generic.v2.test;import ais.common.newui.finance.NewUiStudentArrearsService;import ais.common.newui.finance.NewUiStudentArrearsService.Filter;import ais.common.newui.finance.NewUiStudentArrearsService.Snapshot;public final class StudentArrearsDatabaseSelfTest{private StudentArrearsDatabaseSelfTest(){}public static void main(String[]a){System.setProperty("javax.persistence.validation.mode","none");System.setProperty("hibernate.validator.apply_to_ddl","false");Filter f=new Filter();f.page=0;f.size=10;Snapshot s=new NewUiStudentArrearsService().load(f);check(s.total>=0&&s.rows.size()<=10,"rows");check(s.debt>=0,"debt");if(!s.rows.isEmpty()){NewUiStudentArrearsService.Details d=new NewUiStudentArrearsService().details(s.rows.get(0).id);check(d.charges!=null&&d.payments!=null,"details");}System.out.println("StudentArrearsDatabaseSelfTest OK total="+s.total+" debt="+s.debt);System.exit(0);}private static void check(boolean v,String m){if(!v)throw new IllegalStateException(m);}}
